(function(root){
const copy=x=>JSON.parse(JSON.stringify(x));
function duplicateTrace(e){const seen=new Set(),steps=[];let i=-1;const emit=(text,result=null)=>steps.push(copy({kind:'set',nums:e.nums,i,set:[...seen],text,result}));emit('开始：集合为空，只记数字是否出现。');for(i=0;i<e.nums.length;i++){const value=e.nums[i];emit(`读位置${i}的${value}，先查已见集合。`);if(seen.has(value)){emit(`集合已有${value}，发现不同位置的重复，返回true。`,true);return steps}seen.add(value);emit(`没有出现过，把${value}加入集合。`)}emit('全部读完，没有重复，返回false。',false);return steps}
function palindromeTrace(e){const chars=e.s.split(''),steps=[];let left=0,right=chars.length-1;const valid=c=>typeof c==='string'&&/[A-Za-z0-9]/.test(c);const emit=(text,result=null,pair=null)=>steps.push(copy({kind:'palindrome',chars,left,right,text,result,pair}));emit('开始：左右指针直接放在原串两端。');while(left<right){if(!valid(chars[left])){const c=chars[left];left++;emit(`左侧“${c===' '?'空格':c}”无效，只让左指针前进。`);continue}if(!valid(chars[right])){const c=chars[right];right--;emit(`右侧“${c===' '?'空格':c}”无效，只让右指针后退。`);continue}const a=chars[left].toLowerCase(),b=chars[right].toLowerCase();emit(`有效字符转小写比较：${a} 与 ${b}。`,null,[a,b]);if(a!==b){emit('这对字符不同，返回false，不再读取后续字符。',false,[a,b]);return steps}left++;right--;emit('这对相同，左右一起向内移动。')}emit('指针相遇或交错，有效字符都匹配，返回true。',true);return steps}
function moveZeroTrace(e){const nums=e.nums.slice(),steps=[];let write=0,read=null;const emit=(text,phase='read',fill=null,result=null)=>steps.push(copy({kind:'move',nums,read,write,fill,phase,text,result}));emit('开始：写位置w=0，原数组保持原样。');for(read=0;read<nums.length;read++){emit(`读位置${read}的${nums[read]}。`);if(nums[read]===0){emit('是0，不写入，只继续读。','skip');continue}const value=nums[read];nums[write]=value;emit(`把非零${value}写到位置${write}；尾部旧值暂时保留。`,'write');write++;emit(`写位置前进到${write}，前${write}个非零数字已按原顺序收集。`,'advance')}read=null;for(let i=write;i<nums.length;i++){nums[i]=0;emit(`把尾部位置${i}补成0。`,'fill',i)}emit('尾部清理完成，原数组就是答案。','done',null,nums.slice());return steps}
function binaryTrace(e,insert){const nums=e.nums.slice(),steps=[];let left=0,right=nums.length-1,mid=null;const emit=(text,result=null)=>steps.push(copy({kind:'binary',nums,left,right,mid,target:e.target,insert,text,result}));emit(`开始：闭区间[${left},${right}]。`);while(left<=right){mid=left+Math.floor((right-left)/2);emit(`中点${mid}，值${nums[mid]}与目标${e.target}比较。`);if(nums[mid]===e.target){emit(`命中目标，返回下标${mid}。`,mid);return steps}if(nums[mid]<e.target){left=mid+1;mid=null;emit(`中点及左侧都太小，左边界变成${left}。`)}else{right=mid-1;mid=null;emit(`中点及右侧都太大，右边界变成${right}。`)}}mid=null;emit(insert?`区间为空，返回left=${left}作为插入位置${left===nums.length?'（末尾）':''}。`:'区间为空，目标不存在，返回-1。',insert?left:-1);return steps}

function stockProfitTrace(e){const nums=e.prices.slice(),steps=[];let day=0,minimum=nums.length?nums[0]:null,best=0,profit=null,candidateMinimum=null;const emit=(text,phase,result=null)=>steps.push(copy({kind:'stock',nums,day,minimum,best,profit,candidateMinimum,phase,text,result}));emit(nums.length?'第0天只初始化此前最低价，最佳利润0表示可不交易。':'没有报价，直接返回0。','initial');if(!nums.length){emit('空输入健壮性补测：返回0。','finished',0);return steps}for(day=1;day<nums.length;day++){candidateMinimum=minimum;profit=nums[day]-minimum;emit(`如果第${day}天卖：${nums[day]}减此前最低${candidateMinimum}，候选利润${profit}。`,'compare');if(profit>best)best=profit;emit(`与已有最佳比较，最佳利润现在${best}。`,'best');if(nums[day]<minimum){minimum=nums[day];emit(`今日更低，把最低价更新为${minimum}，留给后续卖出日。候选利润仍是更新前计算的${profit}。`,'minimum')}else emit(`此前最低价${minimum}仍保留。`,'minimum')}profit=null;candidateMinimum=null;emit(`所有卖出日已检查，返回最佳利润${best}。`,'finished',best);return steps}
function removeDuplicateTrace(e){const nums=e.nums.slice(),steps=[];let read=null,write=nums.length?1:0;const emit=(text,phase,result=null)=>steps.push(copy({kind:'compact',nums,read,write,phase,text,result}));emit(nums.length?'先保留第一个数字，write=1；答案只看已保留前缀。':'空数组，唯一数量为0。','initial');if(!nums.length){emit('返回k=0，不读取不存在的位置。','finished',0);return steps}for(read=1;read<nums.length;read++){emit(`读位置${read}的${nums[read]}，与最后保留的${nums[write-1]}比较。`,'compare');if(nums[read]===nums[write-1]){emit('重复，略过；不写入、不增加write。','skip');continue}const value=nums[read];nums[write]=value;emit(`新值${value}写到位置${write}，尾部不用清理。`,'write');write++;emit(`write前进到${write}，前${write}项是不同值。`,'advance')}read=null;emit(`返回k=${write}，只检查前${write}项，后面不计答案。`,'finished',write);return steps}


function longestWindowTrace(e){const chars=e.s.split(''),seen=new Set(),steps=[];let left=0,right=-1,best=0;const emit=(text,phase,included=false,result=null)=>steps.push(copy({kind:'window',chars,left,right,best,set:[...seen],phase,included,text,result}));emit('开始：空窗口，最佳长度0。','initial');for(right=0;right<chars.length;right++){emit(`准备读位置${right}的“${chars[right]===' '?'空格':chars[right]}”。`,'read');while(seen.has(chars[right])){const removed=chars[left];seen.delete(removed);emit(`当前字符重复，先从集合移出左端“${removed}”；左下标下一步再前进。`,'remove');left++;emit(`左边界前进到${left}，继续检查重复。`,'move-left')}seen.add(chars[right]);emit('加入当前字符，现在窗口没有重复。','add',true);best=Math.max(best,right-left+1);emit(`窗口长度${right-left+1}，最佳长度${best}。`,'best',true)}emit(`所有字符已处理，返回最长长度${best}。`,'finished',false,best);return steps}
function sortedPairTrace(e){const nums=e.nums.slice(),steps=[];let left=0,right=nums.length-1,sum=null;const emit=(text,phase,result=null)=>steps.push(copy({kind:'sorted-pair',nums,left,right,sum,target:e.target,phase,text,result}));emit('开始：两端使用不同位置，输出编号从1开始。','initial');while(left<right){sum=nums[left]+nums[right];emit(`${nums[left]}+${nums[right]}=${sum}，与目标${e.target}比较。`,'compare');if(sum===e.target){emit(`命中：内部下标${left}/${right}，返回编号[${left+1},${right+1}]。`,'finished',[left+1,right+1]);return steps}if(sum<e.target){left++;sum=null;emit('和太小，排除左端，向右移动。','move-left')}else{right--;sum=null;emit('和太大，排除右端，向左移动。','move-right')}}emit('没有配对，返回空数组（正式题目保证有唯一解）。','finished',[]);return steps}
function nearbyWindowTrace(e){const nums=e.nums.slice(),seen=new Set(),steps=[];let i=-1,left=0,end=0,pair=null;const emit=(text,phase,result=null)=>steps.push(copy({kind:'nearby',nums,i,left,end,k:e.k,set:[...seen],pair,phase,text,result}));emit('开始：仅保存最近k个以前的位置。','initial');if(e.k<=0){emit('k=0，不同位置距离不能是0，直接false。','finished',false);return steps}for(i=0;i<nums.length;i++){end=i;left=Math.max(0,i-e.k);emit(`检查位置${i}的${nums[i]}；集合来自[${left},${end})。`,'check');if(seen.has(nums[i])){const j=nums.findIndex((v,index)=>index>=left&&index<i&&v===nums[i]);pair=[j,i];emit(`命中位置${j}/${i}，距离${i-j}不超过${e.k}，返回true。`,'finished',true);return steps}seen.add(nums[i]);end=i+1;emit('加入当前值，集合可暂时含k+1个。','add');if(i>=e.k){const old=nums[i-e.k];seen.delete(old);left=i-e.k+1;emit(`为下一轮移出最老位置${i-e.k}的${old}，只保留最近k个。`,'evict')}}end=nums.length;left=Math.max(0,end-e.k);emit('走完没有合格的一对，返回false。','finished',false);return steps}
function reverseListTrace(e){const nums=e.values.slice(),links=nums.map((_,i)=>i+1<nums.length?i+1:null),steps=[];let prev=null,current=nums.length?0:null,saved=null;const emit=(text,phase,result=null)=>steps.push(copy({kind:'linked',nums,links,prev,current,saved,phase,text,result}));emit('开始：previous=null，current是原头。','initial');while(current!==null){saved=links[current];emit(`先保存N${current}原来的next：${saved===null?'null':'N'+saved}。`,'save-next');links[current]=prev;emit(`把N${current}.next改为${prev===null?'null':'N'+prev}。`,'reverse-edge');prev=current;emit(`previous移到N${prev}，已反转部分扩展。`,'move-prev');current=saved;emit(`current移到保存的${current===null?'null':'N'+current}，没有丢掉后半段。`,'move-current')}const result=[];let cursor=prev,guard=0;while(cursor!==null&&guard++<=nums.length){result.push(nums[cursor]);cursor=links[cursor]}if(cursor!==null)throw Error('Trace cycle');emit(`返回新头${prev===null?'null':'N'+prev}，沿next读取新顺序。`,'finished',result);return steps}
function demoTree(values){const nodes=[];if(!values.length||values[0]===null)return{nodes,root:null};nodes.push({id:0,value:values[0],left:null,right:null,level:1});const queue=[0];let cursor=0,pos=1;while(cursor<queue.length&&pos<values.length){const parent=nodes[queue[cursor++]];for(const side of ['left','right']){if(pos>=values.length)break;const value=values[pos++];if(value!==null){const id=nodes.length;nodes.push({id,value,left:null,right:null,level:parent.level+1});parent[side]=id;queue.push(id)}}}return{nodes,root:0}}
function treeDepthTrace(e){const graph=demoTree(e.tree),nodes=graph.nodes,queue=graph.root===null?[]:[graph.root],steps=[],processed=[];let depth=0,remaining=0,current=null;const emit=(text,phase,result=null)=>steps.push(copy({kind:'tree',nums:nodes.map(n=>n.value),nodes,queue,processed,depth,remaining,current,phase,text,result}));emit(graph.root===null?'空树，深度0。':'根节点入队，本层还未开始。','initial');while(queue.length){remaining=queue.length;depth++;emit(`第${depth}层开始，固定本层${remaining}个节点。`,'level');const size=remaining;for(let i=0;i<size;i++){current=queue.shift();emit(`N${current}出队；它的孩子留给下一层。`,'dequeue');const node=nodes[current];if(node.left!==null){queue.push(node.left);emit(`左孩子N${node.left}入队。`,'enqueue-left')}if(node.right!==null){queue.push(node.right);emit(`右孩子N${node.right}入队。`,'enqueue-right')}processed.push(current);remaining--;current=null;emit(`本层剩余${remaining}个待处理，不能把刚入队的孩子混进来。`,'node-done')}}emit(`队列空，最大深度为${depth}（按节点数）。`,'finished',depth);return steps}

function mergeListTrace(e){
const nums=[...e.a,...e.b],offset=e.a.length,links=nums.map((_,i)=>i<offset?(i+1<offset?i+1:null):(i+1<nums.length?i+1:null)),steps=[],selected=[];
let a=offset?0:null,b=e.b.length?offset:null,tail=null,head=null;
const name=id=>id===null?'null':'N'+id;
const emit=(text,phase,result=null)=>steps.push(copy({kind:'merge',nums,links,a,b,tail,head,selected,offset,text,phase,result}));
emit('开始：两条独立输入链，dummy.next=null，tail=dummy。','initial');
while(a!==null&&b!==null){
emit(`比较${name(a)}(${nums[a]})与${name(b)}(${nums[b]})。`,'compare');
const fromA=nums[a]<=nums[b],chosen=fromA?a:b;
if(tail===null)head=chosen;else links[tail]=chosen;
emit(`把${tail===null?'dummy':name(tail)}.next接到${name(chosen)}；输入游标和tail尚未前进。`,'attach');
if(fromA)a=links[chosen];else b=links[chosen];
emit('移动选中链的输入头到它原来的next。','advance-input');
tail=chosen;selected.push(chosen);emit(`tail前进到${name(tail)}，已选择前缀增加一个节点。`,'advance-tail');
}
const rest=a!==null?a:b;if(tail===null)head=rest;else links[tail]=rest;
emit(`一条链耗尽，把剩余后缀${name(rest)}整体接到尾部。`,'append-rest');
const result=[],ids=[];let cursor=head;while(cursor!==null){if(ids.includes(cursor))throw Error('Trace cycle');ids.push(cursor);result.push(nums[cursor]);cursor=links[cursor]}
emit('返回dummy.next；原节点全部恰好一次，哨兵不在答案中。','finished',result);return steps;
}

const traces={mergeListTrace,duplicateTrace,palindromeTrace,moveZeroTrace,binarySearchTrace:e=>binaryTrace(e,false),searchInsertTrace:e=>binaryTrace(e,true),stockProfitTrace,removeDuplicateTrace,longestWindowTrace,sortedPairTrace,nearbyWindowTrace,reverseListTrace,treeDepthTrace};
root.EXTRA_TRACES=traces;Object.assign(root.Algorithms,traces);
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

function renderDailyState(id,s){const values=s.nums||s.chars||[],name=id=>id===null?'null':'N'+id;let start=0,end=values.length;
if(s.kind==='window'){start=s.left;end=s.phase==='finished'?values.length:s.included?s.right+1:Math.max(0,s.right)}
if(s.kind==='nearby'){start=s.left;end=s.end}
const tokens=values.map((value,i)=>{const labels=[];let active=false,found=false,excluded=false;
if(s.kind==='window'){if(i===s.left)labels.push('左');if(i===s.right){labels.push('读右');active=true}found=i>=start&&i<end;excluded=!found&&!active}
if(s.kind==='nearby'){active=i===s.i;if(active)labels.push('当前');found=i>=start&&i<end;excluded=!found&&!active;if(s.pair&&s.pair.includes(i)){labels.push('匹配');found=true}}
if(s.kind==='sorted-pair'){if(i===s.left){active=true;labels.push('左')}if(i===s.right){active=true;labels.push('右')}excluded=i<s.left||i>s.right;found=Array.isArray(s.result)&&s.result.length===2&&(i===s.left||i===s.right)}
if(s.kind==='linked'){if(i===s.current){active=true;labels.push('current')}if(i===s.prev){found=true;labels.push('previous')}if(i===s.saved)labels.push('saved')}
if(s.kind==='tree'){active=i===s.current;found=s.queue.includes(i);if(active)labels.push('出队中');if(found)labels.push('队列');excluded=s.processed.includes(i)}
const identity=s.kind==='linked'||s.kind==='tree'?'N'+i:s.kind==='sorted-pair'?'编号'+(i+1)+'/下标'+i:'位置'+i;
return `<div class="token ${active?'active':''} ${found?'found':''} ${excluded?'range-excluded':''}">${esc(value===' '?'·':value)}<small>${identity}${labels.length?' · '+labels.join('/') :''}</small></div>`}).join('');let visual='',state='';
if(s.kind==='window'||s.kind==='nearby'){visual=`<div class="memory-label">${s.kind==='window'?`已纳入窗口[${start},${end})${s.phase==='remove'?'（刚移出左字符，下标随后前进）':''} · best=${s.best}`:`集合位置[${start},${end}) · k=${s.k}${s.phase==='add'?'（暂时多一个，下一步移出最老值）':''}`}</div><div class="memory-cards">${s.set.map(v=>`<span>${esc(v===' '?'空格':v)}</span>`).join('')||'<em>空集合</em>'}</div>`;state=s.kind==='window'?`left=${s.left}，right=${s.right>=values.length?'已结束':s.right}，best=${s.best}`:`当前=${s.i<0?'未进入循环':s.i>=values.length?'已结束':s.i}；保留[${start},${end})${s.pair?'；距离='+String(s.pair[1]-s.pair[0]):''}`}
if(s.kind==='sorted-pair'){visual=s.sum===null?`<div class="memory-label">目标${s.target} · 等待比较两个不同端点</div>`:`<div class="pair-display"><span>${values[s.left]}</span><b>+</b><span>${values[s.right]}</span><b>=</b><span>${s.sum}</span></div>`;state=`内部left=${s.left}，right=${s.right}；返回编号必须各加1`}
if(s.kind==='linked'){visual=`<div class="memory-label">实际next边（同一批节点，不改值）</div><div class="edge-list">${s.links.map((next,i)=>`<div>N${i}(${values[i]}) → ${name(next)}</div>`).join('')||'空链表'}</div>`;state=`previous=${name(s.prev)}；current=${name(s.current)}；saved=${name(s.saved)}`}
if(s.kind==='tree'){const levels=[...new Set(s.nodes.map(n=>n.level))];visual=`<div class="tree-levels">${levels.map(level=>`<div class="memory-label">第${level}层</div><div class="memory-cards">${s.nodes.filter(n=>n.level===level).map(n=>`<span>${n.value}<small>N${n.id}</small></span>`).join('')}</div>`).join('')||'空树'}</div><div class="edge-list">${s.nodes.map(n=>`<div>N${n.id} 左→${name(n.left)}，右→${name(n.right)}</div>`).join('')}</div><div class="memory-label">未处理队列：${s.queue.map(name).join(' → ')||'空'}</div>`;state=`已开始层数=${s.depth}；本层剩余=${s.remaining}；当前=${name(s.current)}`}
if(s.result!==null)visual+=`<div class="result-banner">${s.kind==='linked'?'返回头 '+name(s.prev)+'，值序列 '+esc(JSON.stringify(s.result)):s.kind==='tree'?'最大深度：'+s.result:s.kind==='window'?'最长连续长度：'+s.result:s.kind==='sorted-pair'?'1起编号：'+esc(JSON.stringify(s.result)):'结果：'+s.result}</div>`;
return{tokens,visual,state};}

function renderExtraState(id,s){if(s.kind==='merge'){
const name=id=>id===null?'null':'N'+id;
const tokens=s.nums.map((v,i)=>`<div class="token ${i===s.a||i===s.b?'active':''} ${s.selected.includes(i)?'found':''}">${v}<small>N${i} · ${i<s.offset?'A':'B'}${i===s.a?' / a':''}${i===s.b?' / b':''}${i===s.tail?' / tail':''}</small></div>`).join('');
let visual=`<div class="memory-label">dummy.next → ${name(s.head)} · 已选择前缀：${s.selected.map(name).join(' → ')||'空'}</div><div class="edge-list">${s.links.map((n,i)=>`<div>N${i}(${s.nums[i]}) → ${name(n)}</div>`).join('')||'两条空链'}</div>`;
if(s.result!==null)visual+=`<div class="result-banner">返回头 ${name(s.head)}，值序列 ${esc(JSON.stringify(s.result))}</div>`;
return{tokens,visual,state:`a=${name(s.a)}；b=${name(s.b)}；tail=${s.tail===null?'dummy':name(s.tail)}`};
}if(['window','nearby','sorted-pair','linked','tree'].includes(s.kind))return renderDailyState(id,s);const values=s.nums||s.chars||[];const tokens=values.map((v,i)=>{const labels=[];let active=false,found=false,excluded=false;
if(s.kind==='set'){active=i===s.i;found=s.result===true&&i<=s.i&&values[i]===values[s.i];if(active)labels.push('读')}
if(s.kind==='stock'){if(i===s.day&&s.day<values.length){active=true;labels.push('今日')}const minIndex=values.findIndex(v=>v===s.minimum);if(i===minIndex&&i<=s.day){found=true;labels.push('最低价来源')}}
if(s.kind==='compact'){if(i===s.read){active=true;labels.push('读r')}if(i===s.write&&s.phase!=='finished'){active=true;labels.push('写w')}found=i<s.write;excluded=s.phase==='finished'&&i>=s.write}
if(s.kind==='palindrome'){if(i===s.left){labels.push('左');active=true}if(i===s.right){labels.push('右');active=true}}
if(s.kind==='move'){if(i===s.read){labels.push('读r');active=true}if(i===s.write&&s.phase!=='done'){labels.push('写w');active=true}if(i===s.fill){labels.push('补零');active=true}found=i<s.write}
if(s.kind==='binary'){excluded=i<s.left||i>s.right;if(i===s.left)labels.push('左');if(i===s.right)labels.push('右');if(i===s.mid){labels.push('中点');active=true}found=s.result===i}
return `<div class="token ${active?'active':''} ${found?'found':''} ${excluded?'range-excluded':''}">${esc(v===' '?'·':v)}<small>${s.kind==='stock'?'第'+i+'天':'位置'+i}${labels.length?' · '+labels.join('/'):''}</small></div>`}).join('');let visual='',state='';
if(s.kind==='set'){visual=`<div class="memory-label">已见数字集合</div><div class="memory-cards">${s.set.map(v=>`<span>${esc(v)}</span>`).join('')||'<em>空集合</em>'}</div>`;state=`读位置：${s.i<0?'未开始':s.i<values.length?s.i:'已完成'}；集合：{${s.set.join(', ')}}`}
if(s.kind==='stock'){visual=s.profit===null?'<div class="memory-label">先记报价，卖出必须晚于买入</div>':`<div class="memory-label">本轮候选：今日价 − 计算时的此前最低价</div><div class="pair-display"><span>${values[s.day]}</span><b>−</b><span>${s.candidateMinimum}</span><b>=</b><span>${s.profit}</span></div>`;visual+=`<div class="memory-label">最佳利润：${s.best} · 留给后续的最低价：${s.minimum===null?'无':s.minimum}</div>`;state=`日期=${s.day<values.length?s.day:'已结束'}；此前/后续最低价=${s.minimum===null?'无':s.minimum}；best=${s.best}`}
if(s.kind==='compact'){visual=`<div class="memory-label">已保留前缀[0,${s.write})：${esc(JSON.stringify(values.slice(0,s.write)))}${s.phase==='finished'?'；尾部值不计答案，不补零':''}</div>`;state=`read=${s.read===null?(s.phase==='initial'?'未开始':'已结束'):s.read}；write=${s.write}；最后保留值=${s.write?values[s.write-1]:'无'}`}
if(s.kind==='palindrome'){visual=`<div class="memory-label">${s.pair?'本次有效字符：'+esc(s.pair.join(' ↔ ')):'标点/空格略过，有效字符才比较'}</div>`;state=`左=${s.left}，右=${s.right}${s.left>=s.right?'（相遇或交错）':''}`}
if(s.kind==='move'){visual=`<div class="memory-label">已确定非零前缀：[0, ${s.write})；尾部${s.phase==='done'?'已补零':'暂未完成'}</div>`;state=`读r=${s.read===null?(s.phase==='read'?'未开始':'已完成'):s.read}；写w=${s.write}${s.write===values.length?'（末尾）':''}${s.fill!==null?'；补零位置='+s.fill:''}`}
if(s.kind==='binary'){visual=`<div class="memory-label">目标${s.target} · ${s.left>s.right?'候选区间为空':`闭区间[${s.left}, ${s.right}]`}</div>`;state=`left=${s.left}，right=${s.right}，mid=${s.mid===null?'未读取':s.mid}`}
if(s.result!==null)visual+=`<div class="result-banner">${s.kind==='binary'?(s.insert?'返回位置：':'返回下标：')+s.result+(s.insert&&s.result===values.length?'（合法尾插，不读取nums[n]）':''):s.kind==='compact'?'返回k：'+s.result:s.kind==='stock'?'最大利润：'+s.result:'结果：'+esc(JSON.stringify(s.result))}</div>`;
return{tokens,visual,state};}
root.renderExtraState=renderExtraState;
if(typeof module!=='undefined')module.exports={traces,renderExtraState};
})(typeof window!=='undefined'?window:globalThis);
